layers.vertex:
attribute vec3 aO, aE; attribute float aT; uniform float uTime; varying vec3 vN, vV;
    void main(){
      float u = uTime - aT - 0.10, L = length(aE - aO), tt = L/11.0;
      if (u < 0. || u > tt){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec3 d = (aE - aO)/L, up = vec3(0., 1., 0.), sd = normalize(cross(d, up)), vu = cross(sd, d);
      float f = u/tt, a = u*9.;                              // lobbed on an arc, tumbling
      vec3 C = mix(aO, aE, f) + vec3(0., min(2., .3*L)*4.*f*(1. - f), 0.);
      vec3 ax = normalize(sd + vu*.4); float ca = cos(a), sa = sin(a);
      vec3 p = position*ca + cross(ax, position)*sa + ax*dot(ax, position)*(1. - ca);
      vec3 nn = normal*ca + cross(ax, normal)*sa + ax*dot(ax, normal)*(1. - ca);
      vec3 P = C + p; vN = nn; vV = normalize(cameraPosition - P);
      gl_Position = projectionMatrix*viewMatrix*vec4(P, 1.);
    }

layers.fragment:
uniform vec3 uGold, uMoon; varying vec3 vN, vV;
    void main(){ vec3 n = normalize(vN); float l = .18 + .7*max(dot(n, uMoon), 0.), rim = pow(1. - abs(dot(n, normalize(vV))), 3.);
      gl_FragColor = vec4(vec3(.16, .26, .1)*l + uGold*(.1 + rim*.9)*.8, 1.); }   // dark green sac, toxic rim

layers.vertex:
attribute vec3 aO; attribute float aT, aK; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){
      float u = uTime - aT, life = aK < .5 ? .2 : (aK < 1.5 ? .55 : .28);
      if (u < 0. || u > life){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK;
      if (aK < .5 || aK > 1.5){
        vec4 mv = viewMatrix*vec4(aO,1.); mv.xyz += normalize(-mv.xyz)*.3;
        float S = aK < .5 ? .4 : .5; mv.xy += position.xy*S; vP = position.xy*S; gl_Position = projectionMatrix*mv;
      } else {
        float S = .62; vP = position.xy*S;
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.);
      }
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float seg(vec2 p, vec2 a, vec2 b){ vec2 pa = p-a, ba = b-a; float h = clamp(dot(pa,ba)/dot(ba,ba), 0., 1.); return length(pa - ba*h); }
    void main(){
      vec2 p = vP; float lum = 0., hot = 0.;
      if (vK > 1.5){
        // rear flash (Interrupt): an asymmetric burst of rays from the stab point — long up-and-forward, short elsewhere
        float r = length(p), a = atan(p.y, p.x), t = vU/.28, f = pow(1. - t, 1.6)*(vU < .033 ? 1.7 : 1.);
        float N = 9., fa = floor(a/6.2832*N + .5), ac = fa/N*6.2832;
        float h = fract(sin(fa*37.1)*4375.5);
        float L = (.1 + .3*pow(max(0., cos(ac - .75)), 2.) + .06*h)*(1. - pow(1. - clamp(vU/.07, 0., 1.), 3.));
        float d = abs(sin(a - ac))*r, w = .014*(1. - r/max(L, .01)) + .003;
        float ray = exp(-pow(d/w, 2.))*smoothstep(L, L*.55, r)*smoothstep(.02, .06, r);
        lum += ray*f*1.2 + exp(-r*r*60.)*f*1.4; hot += ray*f*.5 + exp(-r*r*200.)*f;
        lum *= smoothstep(.5, .42, r); hot *= smoothstep(.5, .42, r);
      } else if (vK < .5){
        // splash: a soft burst + droplets thrown out radially, irregular lengths, thinning as they fly
        float t = vU/.2, f = pow(1. - t, 1.4), r = length(p), a = atan(p.y, p.x);
        float k = 1. - pow(1. - clamp(t/.6, 0., 1.), 3.);
        lum += exp(-r*r*(90. + 400.*t))*f*1.3;                               // splat core
        for (int j=0;j<9;j++){
          float fj = float(j), h = fract(sin(fj*71.3)*4375.5), aj = fj*.698 + h*.5;
          vec2 dir = vec2(cos(aj), sin(aj)); float Rj = (.12 + .2*h)*k;       // each droplet travels its own distance
          vec2 q = p - dir*Rj; float sz = (.018 + .014*fract(h*7.))*(1. - .6*t);
          float along = dot(q, dir), across = dot(q, vec2(-dir.y, dir.x));
          lum += exp(-(across*across)/(sz*sz) - (along*along)/(sz*sz*4.))*f;  // stretched along its motion
        }
        hot = lum*.5;
        lum *= smoothstep(.4, .32, r); hot *= smoothstep(.4, .32, r);
      } else {
        // Slow: a thin ring settles inward (weight), three small chevrons point to the centre, then it fades
        float t = vU/.55, f = pow(1. - smoothstep(.45, 1., t), 1.5)*smoothstep(0., .08, t);
        float R = mix(.5, .38, 1. - pow(1. - clamp(t/.3, 0., 1.), 3.)), r = length(p);
        float ring = exp(-pow((r - R)/.009, 2.));
        float ch = 0.;
        for (int i=0;i<3;i++){
          float a = float(i)*2.0944 + .5; vec2 u = vec2(cos(a), sin(a)), n = vec2(-u.y, u.x);
          vec2 q = vec2(dot(p, n), dot(p, u)) - vec2(0., R - .09);   // chevron just inside the ring, tip pointing inward
          float dv = min(seg(q, vec2(0., -.035), vec2(-.045, .025)), seg(q, vec2(0., -.035), vec2(.045, .025)));
          ch += exp(-pow(dv/.007, 2.));
        }
        lum += (ring*.9 + ch*.8)*f; hot += ring*f*.3;
      }
      vec3 outc = mix(uOrange, uGold, .6)*lum + mix(uGold, vec3(1., .96, .88), .6)*hot;
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }

layers.vertex:
attribute vec3 aO; attribute float aT; uniform float uTime; varying vec2 vP; varying float vU;
    void main(){ float u = uTime - aT; if (u < 0. || u > 2.20){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float S = 2.00; vP = position.xy*S; vU = u; gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .025, -position.y*S), 1.); }

layers.fragment:
uniform vec3 uGold,uOrange;varying vec2 vP;varying float vU;
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5);}
float vn(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(h(i),h(i+vec2(1.,0.)),f.x),mix(h(i+vec2(0.,1.)),h(i+vec2(1.,1.)),f.x),f.y);}
void main(){float r=length(vP),a=atan(vP.y,vP.x),R=1.6,grow=smoothstep(0.,.24,vU),fade=1.-smoothstep(1.7,2.2,vU);
float edge=R*grow*(.93+.045*sin(a*5.)+.025*sin(a*9.+1.));float inside=smoothstep(edge,edge-.08,r);
vec2 flow=vP*2.2+vec2(.07*sin(vU*.8),vU*.1);float n=vn(flow)*.7+vn(flow*2.3)*.3;
float ripple=pow(.5+.5*sin(r*17.-vU*1.5+n*4.),7.);float wet=pow(max(0.,vn(flow+vec2(.06,.03))-n+.25),6.)*24.;
float bubbles=0.;for(int i=0;i<12;i++){float k=float(i),an=k*2.39996,rad=R*sqrt((k+.5)/13.)*.86;
vec2 c=vec2(cos(an),sin(an))*rad;float cycle=fract(vU*.53+k*.17),sz=(.045+.026*h(vec2(k)))*sin(3.14159*cycle);
float d=length(vP-c);bubbles+=exp(-pow((d-sz)/.012,2.))*sin(3.14159*cycle)*.20;}
vec3 col=mix(vec3(.025,.072,.012),uOrange*.27,smoothstep(.25,.8,n))+uGold*(ripple*.025+wet*.13+bubbles);
float rim=exp(-pow((r-edge)/.024,2.));col=(col*inside+uOrange*rim*.18)*fade;
gl_FragColor=vec4(col,(inside*.91+rim*.10)*fade);}

layers.vertex:
attribute vec3 aO, aE; attribute float aT; uniform float uTime; varying vec2 vP; varying float vK;
    void main(){ float u = uTime - aT; if (u < -.35 || u > 0.12){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float k = clamp(u/0.12, 0., 1.), e = k*k*k;                     // reverse ease-in: holds, then snaps in
      vec3 P = mix(aO, aE, e);
      vec4 mv = viewMatrix*vec4(P, 1.); float S = .07*(1. - .5*e); mv.xy += position.xy*S;
      vP = position.xy; vK = step(0., u)*k + (1. - step(0., u))*(1. + u/.35)*.0; gl_Position = projectionMatrix*mv; }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vK;
    void main(){ float r = length(vP); vec3 o = (uOrange*exp(-r*r*5.) + mix(uGold, vec3(1.), .5)*exp(-r*r*30.))*1.1*smoothstep(1., .8, r);
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }

layers.vertex:
attribute vec3 aO;attribute float aT;attribute vec2 aP;uniform float uTime;varying vec3 vN,vV;varying float vLife;
void main(){float u=uTime-aT;if(u<0.||u>2.2){gl_Position=vec4(2.,2.,2.,1.);return;}float k=fract(u*.75+aP.x),f=sin(3.14159*k);
float radius=aP.y*f;vec3 P=aO+vec3(0.,.03+.28*k*k,0.)+position*radius;vN=normal;vV=normalize(cameraPosition-P);vLife=f;
gl_Position=projectionMatrix*viewMatrix*vec4(P,1.);}

