uniform vec3 uGold,uOrange;varying vec3 vN,vV;varying float vLife;
void main(){float nv=abs(dot(normalize(vN),normalize(vV))),rim=pow(1.-nv,2.5),gloss=pow(max(dot(normalize(vN),normalize(vec3(-.3,.8,.5))),0.),60.);
vec3 c=uOrange*(.11+rim*.26)+uGold*gloss*.38;gl_FragColor=vec4(c,vLife*(.32+rim*.28));}
